-- Changelog Einträge v6.0.0 bis v6.1.6
-- Bestehende Einträge werden nicht dupliziert (DELETE + INSERT)

DELETE FROM changelog WHERE version IN ('6.0.0','6.0.5','6.1.2','6.1.6');

INSERT INTO changelog (version, release_date, content, entry_type) VALUES
('6.0.0', '2026-03-20',
'Rollen & Berechtigungssystem\n- 14 Berechtigungen pro Rolle (plan_view, plan_edit, plan_publish_own, plan_publish_all, etc.)\n- hasPerm()-Funktion mit Rollen-Fallback\n- 9 System-Rollen: Admin, Manager, Teamleiter, Verwaltung, Lager, Techniker, Azubi 1-3\n\nPlan-Entwürfe / Veröffentlichung\n- Entwurfs-System mit plan_drafts-Tabelle\n- \"Meine Änderungen veröffentlichen\" / \"Alle veröffentlichen\"\n- Draft-Badge mit Anzahl, Verlassen-Modal bei Entwürfen\n\nInterne Einträge\n- is_internal-Flag: Einträge die nie veröffentlicht werden\n- Neon-gelb gestrichelte Markierung\n\nInterne Bemerkungen\n- Separates Feld internal_remark neben öffentlichen Bemerkungen\n- Nur mit Berechtigung plan_view_internal sichtbar\n- SVG-Schloss-Icon im Tooltip\n\nChangelog-System\n- Modal \"Was gibt es Neues?\" in der Navigation\n- Typ-Badges: Feature, Bugfix, Verbesserung, Sicherheit',
'feature'),

('6.0.5', '2026-03-20',
'Rollen-Seite komplett neu\n- Grid-Layout: Sidebar mit Rollen-Cards + Hauptpanel\n- Custom Toggle-Switches, gruppierte Berechtigungen mit Icons\n- Benutzer-Überschreibungen (Overrides): grant/deny pro Person\n- Neue Rollen anlegen mit Farbe und Berechtigungs-Vorlage\n\nDauereinsatz Konflikte\n- Pre-Check mit Konflikt-Modal\n- Zeigt gesperrten Urlaub, Überschreibungen, Entwürfe\n\nSicherheits-Hardening\n- Rate-Limiting, Input-Sanitierung, CSRF-Validierung\n- Alle 12 API-Endpoints abgesichert\n- Session-Cookie: httponly, samesite=Strict, secure\n- CSP/HSTS-Header\n\nDatenbank-Optimierung\n- Idempotente Migrationen mit ep_safe_col() / ep_safe_idx()\n- 8 neue Performance-Indexes\n- editing_status: Composite PK, InnoDB\n\nBemerkungen\n- Rotes Dreieck links = interne Bemerkung\n- Oranges Dreieck rechts = öffentliche Bemerkung\n- Beide gleichzeitig sichtbar\n\nBugfixes\n- #1054 target_uid behoben\n- Kommentar-Metadaten nur bei echtem Text\n- save_bulk.php Includes repariert',
'improvement'),

('6.1.2', '2026-03-21',
'Mobile Version\n- Bottom-Navigation: Home, Mein Plan, Profil, Abmelden\n- Desktop-only Seiten zeigen Hinweis auf Mobilgeräten\n- Mein Plan Kalender touch-optimiert\n\niCal-Abo pro User\n- Standard RFC-5545 Feed unter api/ical.php\n- 64-Zeichen-Token, Verwaltung auf Profil-Seite\n- Einsätze, Abwesenheiten, Feiertage\n- Sync alle 15 Minuten\n\nBackup & Restore\n- AES-256-CBC verschlüsselte .epbak-Dateien\n- Max 10 Backups, automatische Rotation\n- Manuelles + Cron-Backup, Restore mit Sicherung\n- Schlüssel-Anzeige in Einstellungen\n\nEntwürfe sichtbar\n- Eigene = blauer Balken am Zellenrand\n- Fremde = gelber Balken + Dreieck + Tooltip mit Autor\n- Legende erweitert\n\nRollen: \"Niemand außer\"\n- 3 Modi: Zusätzlich gewähren, Niemand außer, Verweigern für\n\nNicht veröffentlichen\n- Ein/Aus-Toggle statt Checkbox, feste Box\n\nAudit Log anonymisiert\n- Keine Benutzernamen/IPs in der UI\n- Login-Statistik nur als Tagesaggregate\n\nGesperrte Benutzer\n- Rotes Schloss-Symbol am Namen bei Kontosperre\n\nVeröffentlichung\n- Fremde Entwürfe bleiben erhalten\n- Toast zeigt verbliebene fremde Änderungen',
'feature'),

('6.1.6', '2026-03-22',
'Krankheitstage bei Dauereinsatz\n- Veröffentlichte Krankheitstage werden automatisch übersprungen\n- Eigene Sektion im Konflikt-Modal mit SVG-Icon\n\nMeldungen (Dashboard)\n- Neue Tabelle announcements mit Priorität und Zeitraum\n- Dashboard zeigt aktive Meldungen als farbige Banner\n- Verwaltung unter Einstellungen → Wartung\n\nVerlassen-Warnung\n- Browser-Dialog beim Tab/Fenster schließen bei Entwürfen\n\nChangelog verbessert\n- Scrollbarer Modal-Body, Typ-Auswahl beim Erstellen\n- Farbige Typ-Badges in der Anzeige\n\nKeine Emojis\n- Alle Unicode-Emojis durch SVG-Icons ersetzt\n\nDruckformular\n- Konsolidierter Print-Block, globales print-color-adjust\n- Responsive-CSS auf screen-only umgestellt\n- Proportionen optimiert: Name 44px, Tageszellen auto\n- WOT-Spalte im Druck ausgeblendet, Seitenränder 3mm\n\nMobile\n- Desktop-Buttons auf Mobilgeräten ausgeblendet\n- Mein Plan vollständig touch-optimiert\n\nBugfixes\n- Druckseite weiß: Mobile-CSS hat Content ausgeblendet\n- Einstellungsseite: Meldungen-Panel korrekt positioniert',
'feature');
